const api=OwaysAPI.request,E=OwaysAPI.escape,$=s=>document.querySelector(s);function status(m){$('#status').textContent=m;if(m){$('#notice-text').textContent=m;$('#admin-notice').hidden=false;$('#admin-notice').classList.remove('error')}}async function run(fn){try{await fn()}catch(e){status(e.message);$('#admin-notice').classList.add('error')}}async function refresh(){const [c,s,o]=await Promise.all([api('/api/admin/categories'),api('/api/admin/services'),api('/api/admin/orders')]);$('#admin-stats').innerHTML=[['إجمالي الطلبات',o.orders.length],['بانتظار المراجعة',o.orders.filter(x=>x.fulfillment_status==='review').length],['الخدمات',s.services.length],['التصنيفات',c.categories.length]].map(([label,value])=>`<article><small>${E(label)}</small><strong>${value}</strong></article>`).join('');$('#category-select').innerHTML=c.categories.map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join('');$('#categories').innerHTML=c.categories.map(c=>`<p>${E(c.name)}</p>`).join('');$('#services').innerHTML=s.services.map(s=>`<article class="portal-row"><div><b>${E(s.name)}</b><small>${E(s.category_name)} · ${E(s.status)}</small></div><a class="button outline" href="/account?service=${encodeURIComponent(s.slug)}">معاينة الطلب</a></article>`).join('');$('#orders').innerHTML=o.orders.length?o.orders.map(o=>`<article class="portal-row"><div><b>${E(o.public_reference)}</b><small>${E(o.full_name)} · ${E(o.phone)}</small><small>${E(o.fulfillment_status)} · ${E(o.payment_status)}</small></div><button class="button outline" data-order="${E(o.id)}">مراجعة الطلب</button></article>`).join(''):'<p>لا توجد طلبات.</p>'}
$('#category-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/categories',Object.fromEntries(new FormData(e.target)));e.target.reset();await refresh();status('تم حفظ التصنيف.')})};$('#add-requirement').onclick=()=>{const row=document.createElement('div');row.className='requirement-row';row.innerHTML='<label>معرّف الحقل<input data-key required pattern="[a-z][a-z0-9_]*" dir="ltr"></label><label>اسم الحقل<input data-label required></label><label>النوع<select data-type><option value="text">نص</option><option value="email">بريد إلكتروني</option><option value="phone">هاتف</option><option value="url">رابط</option><option value="number">رقم</option><option value="textarea">نص طويل</option><option value="select">اختيار</option></select></label><label>شرح الإدخال<input data-help></label><label>خيارات الاختيار، خيار في كل سطر<textarea data-options></textarea></label><label><input type="checkbox" data-required checked>مطلوب</label><button type="button" class="button outline" data-remove-field>حذف الحقل</button>';$('#requirements').append(row)};$('#service-form').onsubmit=e=>{e.preventDefault();run(async()=>{if(imageBusy){status('انتظر حتى ينتهي تجهيز الصورة.');return}const b=Object.fromEntries(new FormData(e.target));b.image=serviceImage;b.features=b.features.split('\n').map(x=>x.trim()).filter(Boolean);b.instructions={before_order:b.before_order,during_activation:b.during_activation,after_completion:b.after_completion};b.requirements=[...document.querySelectorAll('.requirement-row')].map(r=>({field_key:r.querySelector('[data-key]').value,label:r.querySelector('[data-label]').value,input_type:r.querySelector('[data-type]').value,required:r.querySelector('[data-required]').checked,help_text:r.querySelector('[data-help]').value,options:r.querySelector('[data-options]').value.split('\n').map(x=>x.trim()).filter(Boolean)}));await api('/api/admin/services',b);e.target.reset();clearServiceImage();$('#requirements').innerHTML='';updateDuration();serviceForm.elements.pricing_mode.dispatchEvent(new Event('change'));setServiceStep(0);await refresh();status('تم حفظ الخدمة وباقتها.')})};document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){$('#orders-tab').hidden=tab.dataset.tab!=='orders';$('#catalog-tab').hidden=tab.dataset.tab!=='catalog';$('#contact-tab').hidden=tab.dataset.tab!=='contact';if(tab.dataset.tab==='contact')run(loadContact);const category=tab.dataset.view==='categories';$('#category-editor').hidden=!category;$('#service-editor').hidden=category;$('#services-list').hidden=category;document.querySelectorAll('.sidebar-link[data-tab]').forEach(button=>button.classList.toggle('active',button===tab));status('')}const remove=e.target.closest('[data-remove-field]');if(remove)remove.closest('.requirement-row').remove();const order=e.target.closest('[data-order]');if(order)run(async()=>{const o=await api('/api/admin/orders/'+order.dataset.order);$('#order-detail').hidden=false;$('#order-detail').innerHTML=`<h2>${E(o.public_reference)}</h2><p>${E(o.full_name)} · ${E(o.phone)}</p>${o.items.map(i=>`<h3>${E(i.package_snapshot.service_name)} — ${E(i.package_snapshot.name)}</h3>${i.answers.map(a=>`<p>${E(a.field_key)}: ${E(a.value_json)}</p>`).join('')}`).join('')}<form id="update-order"><label>الحالة<select name="status"><option value="review">قيد المراجعة</option><option value="awaiting_customer">بانتظار إجراء من العميل</option><option value="ready">جاهز للتنفيذ</option><option value="processing">قيد التنفيذ</option><option value="cancelled">ملغي</option></select></label><label>رسالة ظاهرة للعميل<textarea name="note"></textarea></label><button class="button">حفظ التحديث</button></form><p class="fine">التنفيذ يتطلب دفعًا مؤكدًا. إدارة الدفع وإكمال التفعيل لم تُفعّل في هذا الإصدار.</p>`;$('#update-order').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/orders/'+o.id,Object.fromEntries(new FormData(e.target)));await refresh();status('تم تحديث الطلب.')})}})});run(async()=>{const u=(await api('/api/auth/me')).user;if(u.role!=='admin')throw Error('هذه الصفحة للأدمن فقط.');$('#admin-content').hidden=false;await refresh()});

let serviceStep=0;function setServiceStep(index){serviceStep=index;document.querySelectorAll('[data-service-step]').forEach(el=>el.hidden=Number(el.dataset.serviceStep)!==index);document.querySelectorAll('[data-step-label]').forEach(el=>el.classList.toggle('active',Number(el.dataset.stepLabel)===index));$('#previous-step').hidden=index===0;$('#next-step').hidden=index===3;$('#save-service').hidden=index!==3;$('#wizard-status').textContent='الخطوة '+(index+1)+' من 4'}
$('#next-step').onclick=()=>{const active=document.querySelector('[data-service-step="'+serviceStep+'"]');for(const field of active.querySelectorAll('input,select,textarea'))if(!field.checkValidity()){status('تحقق من الحقل: '+(field.closest('label')?.childNodes[0]?.textContent?.trim()||'بيانات الخدمة'));$('#admin-notice').classList.add('error');field.reportValidity();return}if(serviceStep===0&&!$('#category-select').value){status('أضف تصنيفًا أولًا من قسم التصنيفات.');return}setServiceStep(Math.min(3,serviceStep+1))};$('#previous-step').onclick=()=>setServiceStep(Math.max(0,serviceStep-1));
const serviceForm=$('#service-form');serviceForm.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.tagName==='INPUT'&&serviceStep<3){event.preventDefault();$('#next-step').click()}});
const kind=serviceForm.elements.kind;function updateDuration(){const subscription=kind.value==='subscription';for(const key of ['duration_value','duration_unit']){const field=serviceForm.elements[key];field.disabled=!subscription;field.required=subscription;field.closest('label').hidden=!subscription}}kind.addEventListener('change',updateDuration);updateDuration();serviceForm.elements.pricing_mode.addEventListener('change',()=>{const price=serviceForm.elements.price;price.required=serviceForm.elements.pricing_mode.value==='fixed';price.disabled=!price.required;price.closest('label').hidden=!price.required});serviceForm.elements.pricing_mode.dispatchEvent(new Event('change'));setServiceStep(0);

$('#dismiss-notice').onclick=()=>$('#admin-notice').hidden=true;
let serviceImage=null,imageBusy=false;
function clearServiceImage(){serviceImage=null;$('#service-image').value='';$('#image-preview').hidden=true;$('#service-image-preview').removeAttribute('src');$('#image-feedback').textContent=''}
$('#remove-service-image').onclick=clearServiceImage;
$('#service-image').onchange=async()=>{const file=$('#service-image').files[0];if(!file)return;imageBusy=true;$('#next-step').disabled=true;$('#image-feedback').textContent='جارٍ تجهيز الصورة…';let objectURL;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('اختر صورة JPG أو PNG أو WebP.');if(file.size>8*1024*1024)throw Error('الصورة أكبر من 8 ميغابايت.');objectURL=URL.createObjectURL(file);const image=new Image();image.src=objectURL;await image.decode();if(image.naturalWidth*image.naturalHeight>40000000)throw Error('أبعاد الصورة كبيرة جدًا.');const canvas=document.createElement('canvas');canvas.width=960;canvas.height=600;const ctx=canvas.getContext('2d');ctx.fillStyle='#edf2f7';ctx.fillRect(0,0,960,600);const scale=Math.max(960/image.naturalWidth,600/image.naturalHeight);const w=image.naturalWidth*scale,h=image.naturalHeight*scale;ctx.drawImage(image,(960-w)/2,(600-h)/2,w,h);let quality=.84,data=canvas.toDataURL('image/jpeg',quality);while(data.length>360000&&quality>.4){quality-=.1;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>360000)throw Error('تعذر ضغط الصورة؛ اختر صورة أبسط.');serviceImage=data;$('#service-image-preview').src=data;$('#image-preview').hidden=false;$('#image-feedback').textContent='الصورة جاهزة للعرض بمقاس 960 × 600.'}catch(e){status(e.message);$('#admin-notice').classList.add('error');clearServiceImage()}finally{if(objectURL)URL.revokeObjectURL(objectURL);imageBusy=false;$('#next-step').disabled=false}};
async function loadContact(){const r=await api('/api/admin/contact');for(const key of ['whatsapp','email','phone','hours','address'])$('#contact-form').elements[key].value=r[key]||''}
$('#contact-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/contact',Object.fromEntries(new FormData(e.target)));status('تم حفظ معلومات التواصل.')})};
document.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.isComposing||event.shiftKey||event.ctrlKey||event.altKey||event.metaKey)return;if(event.target.tagName==='TEXTAREA')return;const form=event.target.closest('form');if(!form||form.id==='service-form')return;if(event.target.tagName==='INPUT'){event.preventDefault();form.requestSubmit()}});
document.querySelectorAll('form').forEach(form=>form.addEventListener('invalid',event=>{status('يرجى مراجعة الحقل المحدد وإكمال البيانات المطلوبة.');$('#admin-notice').classList.add('error')},true));
